# handling host machine used to run iperf on
import time
import six
import moler
from moler.device.device import DeviceFactory
from moler.cmd.unix import sudo
from moler.device.unixremote import UnixRemote
from moler.device.unixremote2 import UnixRemote2
from moler.io.raw.sshshell import ThreadedSshShell


def is_local_machine(host):
    """Check if host is localhost"""
    if (host == 'localhost') or (host == '127.0.0.1'):
        return True
    return False


def get_conn_hops2adb_shell(serial_number, expected_adb_prompt=None):
    """Construct ADB_SHELL connection hops for moler device state machine"""
    expected_prompt = expected_adb_prompt
    from_state = 'UNIX_REMOTE'
    conn_hops = {
        from_state: {
            'ADB_SHELL': {  # to state
                'execute_command': 'adb_shell',  # via command
                'command_params': {  # with params
                    'serial_number': serial_number,
                    'expected_prompt': expected_prompt,
                }
            }
        }
    }
    return from_state, conn_hops


def get_conn_hops2adb_shell_root(root_password):
    """Construct ADB_SHELL_ROOT connection hops for moler device state machine"""
    from_state = 'ADB_SHELL'
    conn_hops = {
        from_state: {
            'ADB_SHELL_ROOT': {  # to state
                'execute_command': 'su',  # via command
                'command_params': {  # with params
                    'password': root_password,
                }
            }
        }
    }
    return from_state, conn_hops


def get_conn_hops2unix_remote_root(root_password):
    """Construct UNIX_REMOTE_ROOT connection hops for moler device state machine"""
    from_state = 'UNIX_REMOTE'
    conn_hops = {
        from_state: {
            'UNIX_REMOTE_ROOT': {  # to state
                'execute_command': 'su',  # via command
                'command_params': {  # with params
                    'password': root_password,
                }
            }
        }
    }
    return from_state, conn_hops


def create_device(dev_name, dev_def):
    """
    Create moler device based on definition.

    :param dev_name: name for moler
    :param dev_def: dict describing device to create
    :return: requested device.
    """
    conn_description = {'io_type': 'sshshell',  # requires moler >= 1.19.0
                        'host': dev_def['host'],
                        'port': dev_def.get('ssh_port', 22),
                        'login': dev_def.get('login', None),
                        'password': dev_def.get('password', None)}

    # TODO: externally create io to let it be given name, device will take name and logs from moler connection name
    # TODO: that would enable creating device logs that show entries from connection open
    # # io_type = 'sshshell'  # requires newest moler
    # # io_constructor_kwargs = {'host': dev_def['host'],
    # #                          'login': dev_def['login'],
    # #                          'password': dev_def['password']}
    # io_type = 'terminal'
    # io_constructor_kwargs = {}
    # io_connection = get_connection(io_type=io_type, **io_constructor_kwargs)
    # io_connection.name = dev_name
    # io_connection.moler_connection.name = dev_name
    # TODO: no way to pass already created io_connection into DeviceFactory.get_device()
    # TODO: conn_description misses io_connection param, requires io_type

    conn_hops = {}
    if is_local_machine(host=dev_def['host']):
        class2create = 'moler.device.unixlocal.UnixLocal'
        conn_description = {'io_type': 'terminal'}
    else:
        class2create = 'moler.device.unixremote2.UnixRemote2'
        if 'root_password' in dev_def:
            from_state, hop2uxrmroot = get_conn_hops2unix_remote_root(root_password=dev_def['root_password'])
            conn_hops.update(hop2uxrmroot)

    if 'adb' in dev_def:
        # Moler doesn't have StateMachine that jumps to ADB directly from UNIX_LOCAL (need to go via UNIX_REMOTE)
        class2create = 'moler.device.adbremote2.AdbRemote2'
        from_state, hop2adb = get_conn_hops2adb_shell(serial_number=dev_def['adb']['serial_number'],
                                                      expected_adb_prompt=dev_def['adb']['expected_prompt'])
        if from_state in conn_hops:
            conn_hops[from_state].update(hop2adb[from_state])
        else:
            conn_hops.update(hop2adb)

        from_state, hop2adbroot = get_conn_hops2adb_shell_root(root_password='')  # 'su' on adb_shell doesn't need password
        # if there is a case where 'su' at adb_shell needs password
        # then we need to add config setting like:
        #    adb:
        #        root_password: xxxxxxx
        # and then pass it like:
        #     if 'root_password' in dev_def['adb']:
        #         get_conn_hops2adb_shell_root(root_password=dev_def['adb']['root_password'])
        if from_state in conn_hops:
            conn_hops[from_state].update(hop2adbroot[from_state])
        else:
            conn_hops.update(hop2adbroot)

    moler_devices_config = {
        'DEVICES': {
            dev_name + "_src": {
                'DEVICE_CLASS': class2create,
                'CONNECTION_HOPS': conn_hops,
                'CONNECTION_DESC': conn_description,
            }
        }
    }
    moler.config.load_device_from_config(config=moler_devices_config, add_only=True)
    # new_device = DeviceFactory.get_device(name=dev_name)
    new_device = DeviceFactory.get_cloned_device(source_device=dev_name + "_src", new_name=dev_name,
                                                 lazy_cmds_events=True)

    return new_device


def get_device(device_def, data_traffic_name, endpoint_name, logger):
    """
    Get moler device to use for iperf.

    :param device: either name of moler device defined in configuration or dict describing device to create
    :param endpoint_name: 'UE_PC' or 'APP_SVR'.
    :return: requested device.
    """
    connection_name = f"{data_traffic_name}_{endpoint_name}"
    start_time = time.time()
    if isinstance(device_def, six.string_types):
        dev_name = device_def  # create new device based on existing moler device registered under dev_name name
        logger.info(f'creating device {connection_name} from {dev_name}')
        # hot-fix before new moler release is available
        new_device = DeviceFactory.get_cloned_device(source_device=dev_name, new_name=connection_name,
                                                     lazy_cmds_events=True)
        duration = time.time() - start_time
        logger.info(f'DONE creating device {connection_name} from {dev_name} - took {duration:.3f} [sec]')
    else:
        logger.info(f'creating device {connection_name} from {device_def}')
        new_device = create_device(dev_name=connection_name, dev_def=device_def)
        duration = time.time() - start_time
        logger.info(f'DONE creating device {connection_name} from {device_def} - took {duration:.3f} [sec]')
    return new_device


def find_ssh_passwd(host_device):
    """Find password used to ssh into device"""
    password = ''
    if isinstance(host_device.io_connection, ThreadedSshShell):
        password = host_device.io_connection.sshshell.password
    elif isinstance(host_device, UnixRemote) or isinstance(host_device, UnixRemote2):
        password = _find_ssh_passwd4terminalio(host_device._configurations['CONNECTION_HOPS'])
    return password


def _find_ssh_passwd4terminalio(connection_hops):
    password = ''
    if ('UNIX_LOCAL' in connection_hops) and ('UNIX_REMOTE' in connection_hops['UNIX_LOCAL']):
        hop_def = connection_hops['UNIX_LOCAL']['UNIX_REMOTE']
        if (hop_def['execute_command'] == 'ssh') and ('password' in hop_def['command_params']):
            password = hop_def['command_params']['password']
    return password


def get_iperf_command_object(host_device, iperf_options, iperf_path='', need_sudo=False, sudo_password=''):
    """
    Return moler iperf Command object.

    May need wrapping in sudo command.

    :param host_device: moler device that creates iperf command
    :param iperf_options: options to run iperf with
    :param iperf_path: (optional) path to iperf binaries on host
    :param need_sudo: (optional) True means run iperf via sudo
    :param sudo_password: (optional) password for sudo
    :return: iperf command object
    """
    iperf_cmd = host_device.get_cmd(cmd_name="iperf2", cmd_params={"options": iperf_options})
    if iperf_path:
        path_sep = '' if iperf_path.endswith("/") else "/"
        iperf_cmd.command_path = iperf_path + path_sep
    if need_sudo:
        sudo_iperf_cmd = host_device.get_cmd(cmd_name="sudo",
                                             cmd_params={"password": sudo_password, "cmd_object": iperf_cmd})
        iperf_cmd = sudo_iperf_cmd
    return iperf_cmd


def retrieve_real_iperf_command_object(command_object):
    """Retrieve real Iperf2 command if wrapped inside Sudo command"""
    if isinstance(command_object, sudo.Sudo):
        return command_object.cmd_object
    return command_object
